<script setup lang="ts">
import {computed} from 'vue';import AppEmptyState from './AppEmptyState.vue';import type {Theme,Section,Vod} from '@/domain/types';import {moduleItems} from '@/domain/presentation';import {assetUrl} from '@/services/api';
const props=defineProps<{theme:Theme;section:Section;items:Vod[];editing?:boolean;selected?:boolean}>();const emit=defineEmits<{open:[vod:Vod];select:[id:string];more:[section:Section]}>();const list=computed(()=>moduleItems(props.section,props.items));const style=computed(()=>props.section.style||'grid3');const cols=computed(()=>props.section.columns||3);const vars=computed(()=>({'--cols':cols.value,'--gap':(props.section.gap??8)+'px','--radius':(props.section.radius??props.theme.layout.posterRadius)+'px','--ratio':['2/3','3/4','16/9','1/1'].includes(props.section.ratio||'')?(props.section.ratio||'2/3').replace('/',' / '):'2 / 3'}));
function open(v:Vod){if(props.editing)emit('select',props.section.id);else emit('open',v);}
</script>
<template><view class="film-module" :class="{selected,editing}" :style="vars" @click="editing&&emit('select',section.id)"><view v-if="section.title||section.subtitle||section.showMore!==false" class="module-heading"><view><text class="module-title">{{section.title}}</text><text v-if="section.subtitle" class="module-subtitle">{{section.subtitle}}</text></view><text v-if="section.showMore!==false" class="more" @click.stop="editing?emit('select',section.id):emit('more',section)">更多 ›</text></view><view class="films" :class="'style-'+style"><view class="film" tabindex="0" @keydown.enter="open(v)" v-for="(v,i) in list" :key="v.id" @click.stop="open(v)"><view class="poster"><image :src="assetUrl(v.poster)" mode="aspectFill"/><text v-if="style==='ranking'" class="rank">{{String(i+1).padStart(2,'0')}}</text><text v-if="section.showScore!==false&&v.score" class="score">{{v.score}}</text><text v-if="section.showNote!==false&&v.note" class="note">{{v.note}}</text></view><view class="film-copy"><text class="film-title" v-if="section.showTitle!==false">{{v.title}}</text><text v-if="section.showYear" class="year">{{v.year}} · {{v.category}}</text><text v-if="style==='list'||style==='ranking'" class="description">{{v.description}}</text></view></view></view><AppEmptyState v-if="!list.length" :compact="section.title!=='搜索结果'" :title="section.title==='搜索结果'?'没有找到相关影片':'这里暂时还没有影片'" :description="section.title==='搜索结果'?'试试其他片名或关键词':'精彩内容即将上线'"/></view></template>
<style scoped>.film-module{padding:18px 14px;position:relative;border:1px solid transparent}.film-module.editing{cursor:pointer}.film-module.selected{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}.module-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:13px;gap:10px}.module-title{font-size:18px;font-weight:700}.module-subtitle{font-size:10px;color:var(--muted);display:block;margin-top:5px}.more{font-size:11px;color:var(--muted);white-space:nowrap;cursor:pointer}.films{display:grid;gap:var(--gap);grid-template-columns:repeat(var(--cols),minmax(0,1fr))}.film{min-width:0;cursor:pointer}.poster{position:relative;aspect-ratio:var(--ratio);overflow:hidden;border-radius:var(--radius);background:var(--surface)}.poster image{width:100%;height:100%}.score{position:absolute;top:5px;right:5px;background:#0009;color:#f9db93;font-size:10px;padding:2px 4px;border-radius:3px}.note{position:absolute;bottom:0;left:0;right:0;padding:16px 6px 5px;color:#fff;font-size:9px;background:linear-gradient(transparent,#000b);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.film-title{display:block;font-size:12px;margin-top:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.year{display:block;color:var(--muted);font-size:10px;margin-top:5px}.style-scroll{display:flex;overflow:auto;scrollbar-width:none}.style-scroll .film{flex:0 0 37%}.style-list,.style-ranking{grid-template-columns:1fr}.style-list .film,.style-ranking .film{display:flex;gap:13px;align-items:center}.style-list .poster,.style-ranking .poster{width:88px;flex-shrink:0}.film-copy{min-width:0}.description{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:11px;line-height:1.8;color:var(--muted);margin-top:10px}.rank{position:absolute;left:0;top:0;background:#e5b85f;color:#221614;font-size:15px;font-weight:700;padding:4px 9px}.style-mosaic{grid-template-columns:repeat(3,minmax(0,1fr))}.style-mosaic .film:first-child{grid-column:span 2;grid-row:span 2}.style-mosaic .film:first-child .poster{aspect-ratio:3 / 4}</style>